<script setup>
import {ref,computed} from 'vue';import {importTemplate,parseCsv,prepareDramaImport} from './bulkImport.js';import {productionCompanyOptions} from './companies.js';
const props=defineProps({repository:Object,catalog:Object});const emit=defineEmits(['refresh']);const rows=ref([]),error=ref(''),busy=ref(false),fileName=ref('');const invalid=computed(()=>rows.value.filter(r=>r.status==='invalid').length);
function download(example){const url=URL.createObjectURL(new Blob([importTemplate(example)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=example?'剧集导入示例.csv':'剧集批量导入模板.csv';a.click();URL.revokeObjectURL(url);}
async function preview(event){if(busy.value)return;error.value='';rows.value=[];const file=event.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('文件请控制在 5MB 以内');fileName.value=file.name;let grid;if(/\.csv$/i.test(file.name))grid=parseCsv(await file.text());else if(/\.xlsx$/i.test(file.name)){const {readSheet}=await import('read-excel-file/browser');grid=await readSheet(file,{dateFormat:'yyyy-mm-dd'});}else throw Error('支持 CSV 或 XLSX 文件');rows.value=prepareDramaImport(grid,{...props.catalog,companies:productionCompanyOptions(props.catalog.artists)});}catch(e){error.value=e.message;}finally{event.target.value='';}}
async function commit(){if(busy.value||invalid.value||!rows.value.length)return;busy.value=true;error.value='';try{const current=await props.repository.load();for(const row of rows.value){if(row.status==='saved')continue;try{if(current.dramas.some(d=>d.id===row.data.id)){row.status='saved';row.error='';continue;}if(current.dramas.some(d=>[d.titleZh,d.titleEn,d.titleTh].some(name=>name&&[row.data.titleZh,row.data.titleEn,row.data.titleTh].some(n=>n&&n.trim().toLowerCase()===name.trim().toLowerCase()))))throw Error('资料库已有同名剧集，请重新预览检查');row.status='saving';row.error='';await props.repository.save(row.data);current.dramas.push(row.data);row.status='saved';}catch(e){row.status='failed';row.error=e.message;error.value='第 '+row.line+' 行保存失败。此前成功的资料已保留；可修复后重试，不会重复导入。';break;}}emit('refresh');}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><section class="bulk-import"><h3>批量导入剧集</h3><div class="actions"><button type="button" @click="download(false)">下载空白模板</button><button type="button" @click="download(true)">下载填写示例</button><label class="upload">选择 CSV / XLSX<input type="file" accept=".csv,.xlsx" :disabled="busy" @change="preview"></label></div><details><summary>填写说明与列格式</summary><p>每行一部剧，每批最多100部；中文名、英文名、泰语名至少一项。类别、图片链接、每周播出日均用英文分号分隔，如 BL;Bromance、周四;周日。日期填 YYYY-MM-DD，时间填 HH:mm。未定档可不填整组排期。</p><p>卡司格式：艺人名称或ID|角色|主演标记，多位以分号分隔；同名艺人请用ID。公司和平台应先在现有资料库配置。图片第一张为主海报。</p><p>多平台可用“平台排期JSON”列填写完整规则数组（platformId 使用已有平台ID），普通单平台填写常规列即可。阶段调整列格式如 [{"from":"2026-11-12","weekdays":[4,0]}]，0为周日、1至6为周一至周六。</p><p>导入仅新增，不覆盖已有剧集。逐行保存，各行独立事务；成功行不会因后续失败回滚。内容保持管理员私有。</p></details><p v-if="error" role="alert">{{error}}</p><div v-if="rows.length"><p>{{fileName}} · {{rows.length}} 行，{{invalid}} 行需要修正，{{rows.filter(r=>r.status==='saved').length}} 行已保存</p><div class="table-wrap"><table><thead><tr><th>行号</th><th>剧名</th><th>状态／问题</th></tr></thead><tbody><tr v-for="row in rows" :key="row.line"><td>{{row.line}}</td><td>{{row.title||'未填写'}}</td><td>{{({ready:'可导入',invalid:'需修正',saving:'保存中',saved:'已保存',failed:'保存失败'})[row.status]}} {{row.error}}</td></tr></tbody></table></div><button type="button" class="primary" :disabled="!repository||busy||invalid>0||rows.every(r=>r.status==='saved')" @click="commit">{{busy?'正在导入，请勿关闭页面':'确认导入到私有资料库'}}</button><p v-if="!repository">示例预览不可导入正式数据库，请使用正式管理后台。</p></div></section></template>
<style scoped>.bulk-import{margin:20px 0;border:1px solid #dce3d7;padding:20px;background:white;border-radius:12px;font-size:13px}.bulk-import h3{margin:0 0 14px;font-size:17px}.actions{display:flex;gap:12px;flex-wrap:wrap}.bulk-import button,.upload{font:inherit;border:1px solid #d9ded7;border-radius:7px;background:white;padding:8px 12px;cursor:pointer}.upload input{display:block;max-width:220px;margin-top:6px;font-size:12px}.bulk-import details{margin:14px 0;color:#6c7965}.bulk-import p{line-height:1.7}.table-wrap{overflow:auto;max-height:350px;margin-bottom:16px}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:9px;border-bottom:1px solid #e6e9e1;min-width:60px}.primary{background:#4e664d!important;color:white}.bulk-import button:disabled{opacity:.45;cursor:default}</style>
